package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.jsoup.Connection;
import org.jsoup.Jsoup;
import org.jsoup.helper.HttpConnection;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class FormElement_formData_TriageGen0Test {

    private Document doc;
    private FormElement form;

    @Before
    public void setUp() {
        doc = Document.create("");
        form = doc.appendElement("form");
    }

    @Test
    public void testFormData_EmptyForm() {
        List<Connection.KeyVal> data = form.formData();
        assertTrue(data.isEmpty());
    }

    @Test
    public void testFormData_NonSubmittableElement() {
        // Assuming a tag like <div> is not form submittable
        form.appendElement("div");
        List<Connection.KeyVal> data = form.formData();
        assertTrue(data.isEmpty());
    }

    @Test
    public void testFormData_ElementWithoutName() {
        form.appendElement("input").attr("type", "text");
        List<Connection.KeyVal> data = form.formData();
        assertTrue(data.isEmpty());
    }

    @Test
    public void testFormData_TextElement() {
        form.appendElement("input")
                .attr("name", "username")
                .attr("type", "text")
                .attr("value", "john_doe");

        List<Connection.KeyVal> data = form.formData();
        assertEquals(1, data.size());
        assertEquals("username", data.get(0).getKey());
        assertEquals("john_doe", data.get(0).getValue());
    }

    @Test
    public void testFormData_SelectWithSelectedOption() {
        Element select = form.appendElement("select").attr("name", "choice");
        select.appendElement("option").attr("value", "v1").text("One");
        select.appendElement("option").attr("value", "v2").attr("selected", true).text("Two");
        select.appendElement("option").attr("value", "v3").text("Three");

        List<Connection.KeyVal> data = form.formData();
        assertEquals(1, data.size());
        assertEquals("choice", data.get(0).getKey());
        assertEquals("v2", data.get(0).getValue());
    }

    @Test
    public void testFormData_SelectWithMultipleSelectedOptions() {
        Element select = form.appendElement("select").attr("name", "multi");
        select.appendElement("option").attr("value", "v1").attr("selected", true);
        select.appendElement("option").attr("value", "v2").attr("selected", true);

        List<Connection.KeyVal> data = form.formData();
        assertEquals(2, data.size());
        assertEquals("v1", data.get(0).getValue());
        assertEquals("v2", data.get(1).getValue());
    }

    @Test
    public void testFormData_SelectWithNoSelectedOption() {
        Element select = form.appendElement("select").attr("name", "choice");
        select.appendElement("option").attr("value", "v1").text("One");
        select.appendElement("option").attr("value", "v2").text("Two");

        List<Connection.KeyVal> data = form.formData();
        assertEquals(1, data.size());
        assertEquals("v1", data.get(0).getValue());
    }

    @Test
    public void testFormData_SelectWithNoOptions() {
        form.appendElement("select").attr("name", "empty_select");
        List<Connection.KeyVal> data = form.formData();
        assertTrue(data.isEmpty());
    }

    @Test
    public void testFormData_CheckboxChecked() {
        form.appendElement("input")
                .attr("name", "agree")
                .attr("type", "checkbox")
                .attr("value", "yes")
                .attr("checked", true);

        List<Connection.KeyVal> data = form.formData();
        assertEquals(1, data.size());
        assertEquals("agree", data.get(0).getKey());
        assertEquals("yes", data.get(0).getValue());
    }

    @Test
    public void testFormData_CheckboxUnchecked() {
        form.appendElement("input")
                .attr("name", "agree")
                .attr("type", "checkbox")
                .attr("value", "yes");

        List<Connection.KeyVal> data = form.formData();
        assertTrue(data.isEmpty());
    }

    @Test
    public void testFormData_RadioChecked() {
        form.appendElement("input")
                .attr("name", "gender")
                .attr("type", "radio")
                .attr("value", "m")
                .attr("checked", true);

        List<Connection.KeyVal> data = form.formData();
        assertEquals(1, data.size());
        assertEquals("m", data.get(0).getValue());
    }

    @Test
    public void testFormData_RadioUnchecked() {
        form.appendElement("input")
                .attr("name", "gender")
                .attr("type", "radio")
                .attr("value", "m");

        List<Connection.KeyVal> data = form.formData();
        assertTrue(data.isEmpty());
    }

    @Test
    public void testFormData_MixedElements() {
        form.appendElement("input").attr("name", "t").attr("type", "text").attr("value", "val_t");
        form.appendElement("input").attr("name", "c").attr("type", "checkbox").attr("value", "val_c").attr("checked", true);
        form.appendElement("select").attr("name", "s").appendElement("option").attr("value", "val_s");

        List<Connection.KeyVal> data = form.formData();
        assertEquals(3, data.size());
        assertEquals("val_t", data.get(0).getValue());
        assertEquals("val_c", data.get(1).getValue());
        assertEquals("val_s", data.get(2).getValue());
    }
}
